package app.anibrave;
import android.app.Instrumentation;
import android.os.Bundle;
import android.database.Cursor;
import org.json.*;
/** Real SQLite checks in an isolated package; never opens production app databases. */
public final class ContinuationInstrumentation extends Instrumentation {
 private int checks;
 private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);checks++;}
 private JSONObject id(String title,int season,int ep,String host)throws Exception{return new JSONObject().put("title",title).put("season",season).put("part",0).put("episode",ep).put("url","https://"+host+"/watch/"+ep);}
 private JSONObject progress(double position,double duration,double speed,double from,double to)throws Exception{return new JSONObject().put("qualified",true).put("position",position).put("duration",duration).put("speed",speed).put("ranges",new JSONArray().put(new JSONArray().put(from).put(to)));}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{
  getTargetContext().deleteDatabase("anibrave-watch.db");getTargetContext().deleteDatabase("anibrave-continuation.db");
  try(AnimeHistory h=new AnimeHistory(getTargetContext())){h.record("Legacy Season 2",4,"hianime.to","https://hianime.to/watch/4",101,1200);h.record("Legacy Season 2",5,"hianime.to","https://hianime.to/watch/5",313,1200);h.dismiss(AnimeIdentity.key("Legacy Season 2"));}
  ContinuationStore s=new ContinuationStore(getTargetContext());JSONArray initial=s.library();check(initial.length()==2,"migration retains earlier log episodes");JSONObject migrated=initial.getJSONObject(0);check(migrated.getInt("season")==2,"migration retains season");check(migrated.getDouble("position")==313,"migration retains latest timestamp");check(!migrated.getBoolean("completed"),"legacy completion never guessed");check(!s.state("https://crunchyroll.com/",null,1).has("entry"),"legacy global dismissal suppresses relevant last episode (older eligible suppressed below)");
  s.close();s=new ContinuationStore(getTargetContext());check(s.library().length()==2,"migration idempotent after reopen");
  JSONObject i=id("Test Series",2,5,"anikototv.to").put("seriesId","series-42").put("episodeId","episode-5");JSONObject e=s.record(i,progress(313,1000,1.5,0,100));String k=e.getString("key");check(e.getString("seriesId").equals("series-42")&&e.getString("episodeId").equals("episode-5"),"structured site identifiers preserved");check(s.state(i.getString("url"),i,31).has("entry"),"identified watch page permits same-site history");check(!s.state("https://anikototv.to/",null,31).has("entry"),"homepage only offers cross-site history");check(e.getDouble("position")==313,"partial timestamp stored separately from coverage");check(!e.getBoolean("completed"),"position alone cannot complete");
  s.record(i,progress(600,1000,1.5,50,500));e=s.record(i,progress(850,1000,1.5,500,850));check(e.getBoolean("completed"),"merged actual coverage reaches 85 percent");check(e.getJSONArray("ranges").length()==1,"overlapping ranges merged");
  e=s.record(i,progress(20,1000,1.5,0,20));check(e.getBoolean("completed"),"rewatch preserves prior completion");
  JSONObject earlier=id("Test Series",2,2,"anikototv.to");s.record(earlier,progress(70,1000,1,0,70));check(s.library().length()==4,"earlier episode cannot replace later record");
  JSONObject wrongSeason=id("Test Series",1,1,"crunchyroll.com");check(!s.state(wrongSeason.getString("url"),wrongSeason,3).has("entry"),"seasons do not mix");
  check(s.state("https://crunchyroll.com/",new JSONObject().put("kind","home").put("title","Home").put("seriesTitle","Home"),30).has("entry"),"home h1 label does not block recent cross-site offer");check(!s.state("https://crunchyroll.com/news",id("Test Series",2,1,"crunchyroll.com").put("kind","other"),30).has("entry"),"unrelated page matching h1 stays quiet");
  JSONObject matching=id("Test Series",2,1,"crunchyroll.com");JSONObject offer=s.state(matching.getString("url"),matching,3).getJSONObject("entry");String offerKey=offer.getString("key");s.dismiss(matching.getString("url"),offerKey,3);s.record(earlier,progress(80,1000,1,70,80));check(!s.state(matching.getString("url"),matching,3).has("entry"),"checkpoint does not revive dismissed episode");
  JSONObject pending=s.begin(matching.getString("url"),k,3,false);check(pending.getBoolean("search")&&pending.getString("url").contains("/search?q="),"unknown target uses real search route");s.close();s=new ContinuationStore(getTargetContext());check(s.state("https://crunchyroll.com/search?q=Test",null,3).has("pending"),"pending survives navigation and store reopen");
  JSONObject aliased=id("Different localized name",2,17,"crunchyroll.com");check(s.confirm(aliased.getString("url"),aliased,3)!=null,"explicit confirmation learns alias and numbering offset");check(s.learned(aliased.getString("url")).getString("key").equals(k),"confirmed exact URL recovers canonical identity without page labels");check(s.learned("https://crunchyroll.com/watch/unknown")==null,"unknown episode URL cannot inherit identity");s.applied(3);pending=s.begin("https://crunchyroll.com/",k,4,false);check(!pending.getBoolean("search")&&pending.getString("url").endsWith("/17"),"learned exact target preferred");
  JSONObject unlabeled=id("Player",1,5,"hianime.to").put("url","https://hianime.to/watch/manual-5").put("learnAlias",false);s.begin("https://hianime.to/",k,41,false);check(s.confirm(unlabeled.getString("url"),unlabeled,41)!=null,"manual unlabeled confirmation learns exact location");s.applied(41);check(s.learned(unlabeled.getString("url")).getString("key").equals(k),"unlabeled exact location recovers canonical episode");check(!s.state("https://hianime.to/watch/6",id("Player",1,6,"hianime.to"),42).has("entry"),"generic player label is not learned as a series alias");
  s.markApplied(4);check(s.state("https://crunchyroll.com/watch/17",null,4).getJSONObject("pending").getBoolean("applied"),"applied handoff retains explicit continuation card");s.applied(4);JSONObject mapped=s.record(aliased,progress(350,1000,1.5,313,350));check(mapped.getString("key").equals(k),"confirmed aliases and offsets map same episode");
  JSONObject corrected=s.correct(k,new JSONObject().put("position",432));check(corrected.getDouble("position")==432,"manual timestamp correction persisted");check(corrected.getBoolean("completed")&&corrected.getDouble("duration")==1000&&corrected.getJSONArray("ranges").length()>0,"timestamp correction preserves coverage duration completion");check(s.correct(k,new JSONObject().put("position",-1))==null,"invalid timestamp correction rejected");
  check(s.record(id("Test Series",2,8,"crunchyroll.com.evil.test"),progress(1,1000,1,0,20))==null,"host suffix spoof rejected");check(s.record(i,new JSONObject().put("position",900))==null,"unqualified playback rejected");
  pending=s.begin("https://hianime.to/",k,5,true);check(pending.getString("url").contains("crunchyroll.com"),"previous site returns latest saved exact URL");s.getWritableDatabase().execSQL("UPDATE pending SET expires=0 WHERE task=5");check(!s.state("https://crunchyroll.com/",null,5).has("pending"),"expired continuation ignored");
  check(!s.state("https://crunchyroll.com/news",null,9).has("entry"),"unrelated page stays quiet");s.forget(k);check(s.begin("https://crunchyroll.com/",k,4,false)==null,"forget removes learned continuation");s.close();
  try(AnimeHistory h=new AnimeHistory(getTargetContext())){check(h.library().size()==1,"legacy original database untouched");try(Cursor c=h.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM episode_log",null)){c.moveToFirst();check(c.getInt(0)==2,"legacy log count untouched");}}
  try(AnimeHistory h=new AnimeHistory(getTargetContext())){h.deleteEpisode("Legacy Season 2",4);try(Cursor c=h.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM episode_log",null)){c.moveToFirst();check(c.getInt(0)==1,"per-episode deletion preserves other legacy log entries");}h.clearHistory();check(h.library().isEmpty(),"explicit legacy clear removes summaries");}
  s=new ContinuationStore(getTargetContext());s.clear();check(s.library().length()==0,"explicit clear cannot reimport legacy");s.close();
  result.putString("stream",checks+" Android SQLite/continuation checks passed\n");finish(-1,result);
 }catch(Throwable e){result.putString("stream",android.util.Log.getStackTraceString(e));finish(0,result);}}
}
